import sys
sys.dont_write_bytecode=True
import additional_pfp_domain_remaining_audit as a
n=a.read('_notes.json');n['controls'].extend(a.read('_solver_probes.json')['controls'])
def ev(p,*rs):
 p='pfp/domain/'+p;return {'path':p,'sha256':a.row(p)['sha256'],'lines':[list(x) for x in rs]}
rows=[
(110,'Finite structure validator admits wrong-arity out-of-carrier tuples','A unary relation on one element accepts tuple(99,100) via from_json/validate. Tuple relation names and duplicate rows are checked, but arity, element bounds and declared sorts are not. Later hosting may refuse, but this validator is not a complete finite-structure admission boundary.',[ev('solvers/structure.py',(237,265),(280,316))],[132]),
(111,'Solver admission misses negative form and witness-instance capability','AdmitInst(-1,(0,)) is accepted using Python negative indexing, retaining form-1 in state. Separately, a stage with no item capabilities admits NewInst on an existing witness form because witness_inst is never tested. The latter is an actual capability-boundary omission, not just malformed state construction.',[ev('solvers/regime.py',(126,149)),ev('solvers/regimek.py',(137,178)),ev('solvers/stage.py',(34,51))],[133]),
(112,'Unknown requirement and truthy native report can satisfy','refutation falls through empty for unknown requirement objects, so satisfies returnsTrue. A synthetic homology adapter returning boundary_law_verified="false" also satisfies through truthiness. Unbound ports correctly refuse, a positive boundary retained; installed adapter outputs still need exact type and certificate contracts.',[ev('solvers/kinds.py',(423,476))],[134]),
(113,'Extended regime canonical key omits operative data','Holonomy req_json serializes only word and omits tables; canonical_k therefore equates otherwise identical regimes carrying different matrices. It also omits new_forms_allowed, which changes available response classes. These keys are incomplete for operational identity even when structural isomorphism itself is correct.',[ev('solvers/kinds.py',(520,543)),ev('solvers/search.py',(193,213))],[135]),
(114,'Sort pruning can falsely certify finite exhaustion','For unary witness form1 sorted by claimform0 with only datum0 in the sort, a Closure with empty body demands form1(datum1). pruning_sound skips integer head arguments and returnsTrue; pruned search reports CLOSED, unpruned search finds NewInst(1,(1,)) at cost1. Independent count matches the wrong pruned class, so counting alone does not prove sound pruning.',[ev('solvers/search.py',(52,98),(101,132),(324,359))],[136]),
(115,'Stage certifier accepts fabricated exhaustion and phantom residual','A proposal supplies nonexistent residual ID, fake source exhaustion/family digest, self-declared nontrivial/down evidence and a datum addition that leaves its real requirement false; all11 certify conditions pass. licensed also accepts11duplicate condition1 records, and execute trusts those records under a supplied granted Licence. No source/receipt binding is checked at execution; this is not a claim of bypassing an external authenticated human licence.',[ev('solvers/stage.py',(243,281),(315,329))],[137]),
(116,'Caller prior score can turn an unchanged state into descent','execute_retraction_turn trusts prior_score. Increasing its active_count by1 and supplying empty delta produces DESCENT with an unchanged child state. Evidence hashes omit actual source regime and port proof, so trusted caller caching must be explicit or recomputed.',[ev('solvers/retraction.py',(236,250),(281,355),(357,365))],[138]),
(117,'Cochain exactness assumes unenforced antisymmetry','Claims c(a,b)=0 and c(b,a)=1 coexist; get prefers the requested orientation. The triangle solver still reports exact coboundary because chosen cycles use only one orientation. The constructor checks Fraction values but not antisymmetry, loops or carrier membership; zero selected-cycle sum cannot certify malformed full claims.',[ev('solvers/simplicial_cochain.py',(281,316),(477,518))],[139]),
(118,'Gradient guidance misreports reverse-stored edge values','A valid cochain stored as c(b,a)=-2 gives c(a,b)=2, but generated guidance says a->b=0 because it reads the repaired dictionary directly with zero default. The solver itself computes correct oriented values; the prompt guidance loses that representation convention.',[ev('solvers/cochain_gradient_hook.py',(180,207))],[140]),
(119,'Hook counts an actual descent as stationary and overstates its comparison','The runner updates current_phi before passing it as prior to record_turn_step. A strict3→2 descent leaves receipt stationary_count0 but hook count1. Its narrowest_claim also asserts hinted prevention for an unhinted one-turn incomplete run; deterministic first-chord subtraction is not observed model behavior or cross-cycle interference.',[ev('solvers/cochain_gradient_hook.py',(220,244),(319,351),(400,418))],[141]),
(120,'Cochain evidence hash does not bind input claims or trace','Opposite initial triangle cochains produce the same evidence digest when task/id/mode, absolute initial/final sums and turn counts coincide. The digest excludes carrier structure, initial claims, turn records and hook configuration; it is summary custody, not replay source binding.',[ev('solvers/cochain_gradient_hook.py',(387,398))],[142])]
for num,title,statement,es,ids in rows:n['findings'].append({'id':f'PFPDOMAIN-F{num:03}','title':title,'statement':statement,'evidence':[e['path'] for e in es],'source_evidence':es,'control_ids':[f'PFPDOMAIN-C{i:03}' for i in ids],'status':'confirmed_bounded_source_and_probe','limits':'Read-vetted unchanged local owners on bounded synthetic data. No paid/live models, private state, native adapters or external authorization used.'})
for ident,title,statement,es,ids in [
('CL25','Declared finite search and canonicalization are reusable with validated premises','Finite reading-ladder leaf weights matched all9 deterministic tables, and refined versus brute structural isomorphism agreed for all256pairs of two-point binary relations. Search hashes/counts and replayed histories are useful custody mechanisms, but source-domain validity, pruning soundness and complete operational keys remain separate obligations. No general minimality or infinite theorem follows from this finite control.',[ev('solvers/ladder.py',(97,135),(189,194)),ev('solvers/iso.py',(134,182)),ev('solvers/search.py',(324,378))],[143]),
('CL26','Tree integration supplies an exact finite repair theorem under graph assumptions','On a connected oriented simple graph with an antisymmetric rational cochain, integrating a fixed spanning tree and replacing every chord by potential difference yields a coboundary. Fundamental cycles decouple the chord equations. This is an explicit finite linear construction; its positive cycle-basis norm is basis-dependent, not Phi1 L1 optimum or H1 of a filled simplicial complex. The hook directly installs this answer and does not establish model adherence.',[ev('solvers/simplicial_cochain.py',(11,15),(185,274),(326,342),(438,518)),ev('solvers/cochain_gradient_hook.py',(308,328))],[139,140,141]),
('CL27','PFP authority separation is an interface obligation, not granted by labels','The domain contains explicit None ceilings, typed refusals, frozen claims, source digests and human-licence concepts. Their sound use depends on validated constructors, literal checker outputs, complete source/claim/proof binding and authenticated host policy. A report label such as Certificate, Exact, CertifiedTerminal or all_passed is not independently justified when the owner accepts declared flags, phantom IDs or omitted operative fields. Findings identify concrete local gaps rather than reject the general separation principle.',[ev('solvers/stage.py',(243,329)),ev('mssn_research/grammar/authority_policies.py',(30,100)),ev('stages/demos.py',(48,60))],[117,122,137])]:n['claims'].append({'id':'PFPDOMAIN-'+ident,'title':title,'statement':statement,'evidence':[e['path'] for e in es],'source_evidence':es,'control_ids':[f'PFPDOMAIN-C{i:03}' for i in ids],'status':'bounded_source_and_control_assessment'})
n['pending_followups']=[{'path':'pfp/domain/rewriting/rewrites.py','source':'parent wiki review coordination','status':'resolved_bounded','statement':'Full owner read and C015 confirm parse_boundary(<>) refuses EMPTY_ATOM. The separate MSSN Packet.void/from_wire parser admits <>. This is a grammar-boundary mismatch, not evidence of semantic preservation or eleven equivalent dialects.','source_sha256':a.row('pfp/domain/rewriting/rewrites.py')['sha256'],'reviewed_lines':[[1,150]],'control_ids':['PFPDOMAIN-C015']}]
